    for profile in Profile.objects.using(alias).iterator():
        Plan.objects.using(alias).filter(user_id=profile.user_id).update(
            age=profile.age,
            height=profile.height,
            sex=profile.sex or "unspecified",
            activity=profile.activity or "light",
        )


